import type { SupportedVersions } from "./compute.ts"
export { PROJECT_PACKAGES } from "./compute.ts"
import supportedVersions from "./supported-versions.json" with { type: "json" }

export type { SupportedVersions }

// Generated by `pnpm sync:versions` from the pins in the docs manifest. A test fails when the pins and this file drift apart.
export const SUPPORTED_VERSIONS: SupportedVersions = supportedVersions

export function supportedRange(name: string): string | undefined {
  return (
    SUPPORTED_VERSIONS.requirements[name] ?? SUPPORTED_VERSIONS.packages[name]
  )
}
